{
  "name": "opencode-zellij-tab-status",
  "version": "1.0.1",
  "description": "OpenCode plugin that updates your Zellij tab name to reflect the AI agent status (running, complete, error, question)",
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "scripts",
    "src"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outfile dist/index.js --format esm --target node"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "zellij",
    "terminal",
    "tab",
    "status"
  ],
  "author": "Victor Falcon",
  "license": "MIT",
  "devDependencies": {
    "@opencode-ai/plugin": "1.2.20",
    "bun-types": "latest"
  }
}
